# self similarity: longest common substring between seq and rc(seq) via hashing short seeds then extend
def longest_common(a,b,K=15):
    best=[]
    idx={}
    for i in range(len(b)-K+1):
        idx.setdefault(b[i:i+K],[]).append(i)
    used=set()
    res=[]
    for i in range(len(a)-K+1):
        k=a[i:i+K]
        for j in idx.get(k,[]):
            # extend
            x,y=i,j
            while x>0 and y>0 and a[x-1]==b[y-1]:
                x-=1;y-=1
            e1,e2=x,y
            x,y=i+K,j+K
            while x<len(a) and y<len(b) and a[x]==b[y]:
                x+=1;y+=1
            L=x-e1
            if L>=30:
                res.append((L,e1,e2))
    res.sort(reverse=True)
    return res[:20]
