def common(a,b,K=20,minlen=40):
    idx={}
    for i in range(len(b)-K+1):
        idx.setdefault(b[i:i+K],[]).append(i)
    res=[]
    for i in range(len(a)-K+1):
        for j in idx.get(a[i:i+K],[]):
            x,y=i,j
            while x>0 and y>0 and a[x-1]==b[y-1]: x-=1;y-=1
            s1,s2=x,y
            x,y=i+K,j+K
            while x<len(a) and y<len(b) and a[x]==b[y]: x+=1;y+=1
            L=x-s1
            if L>=minlen: res.append((L,s1,s2))
    # dedupe
    seen=set(); out=[]
    for L,s1,s2 in sorted(res,reverse=True):
        key=(s1,s2)
        if any(abs(s1-a1)<10 and abs(s2-a2)<10 for a1,a2 in seen): continue
        seen.add((s1,s2)); out.append((L,s1,s2))
