def hairpins(s,start,end,minstem=6,minloop=3,maxloop=30):
    res=[]
    for i in range(start,end):
        for j in range(i+minstem+minloop, min(i+minstem+maxloop+1,end+1)):
            # stem: s[i:x] pairs with reverse of s[y:j] where x=i+L, y=j-L
            L=0
            while i+L<j-1-L and comp[s[i+L]]==s[j-1-L]:
                L+=1
            if L>=minstem:
                res.append((L,s[i:i+L],s[j-L:j],i,j,j-i))
    res.sort(reverse=True)
    return res[:5]
